BEGIN;
CREATE OR REPLACE FUNCTION office_private.inst_initial(r text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN r IN('organizations','branches','bodies','funds','facilities','people','attendance') THEN CASE WHEN r='people' THEN 'active' WHEN r='attendance' THEN 'recorded' ELSE 'active' END WHEN r='safeguarding' THEN 'reported' WHEN r='privacy_requests' THEN 'open' WHEN r IN('bank_lines','credentials') THEN 'recorded' WHEN r IN('appointments','staff_assignments') THEN 'proposed' ELSE 'draft' END $$;
CREATE OR REPLACE FUNCTION office_private.inst_cap_for_resource(r text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN r IN('organizations','branches','bodies','appointments','meetings','resolutions') THEN 'governance' WHEN r IN('funds','budgets','contributions','payment_requests','bank_lines','reconciliations') THEN 'finance' WHEN r IN('facilities','assets','asset_moves') THEN 'facilities' WHEN r IN('programmes','events','attendance') THEN 'programmes' WHEN r IN('staff_assignments','credentials') THEN 'staff' WHEN r IN('safeguarding') THEN 'safeguarding' WHEN r IN('filings','evidence','privacy_requests') THEN 'privacy' ELSE NULL END $$;
CREATE OR REPLACE FUNCTION office_private.inst_safe_row(r record) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$ DECLARE d jsonb:='{}'; k text; allowed text[]; BEGIN allowed:=CASE r.resource WHEN 'organizations' THEN ARRAY['code','name','jurisdiction','legal_form','registration_authority','registration_reference','constitution_reference','address_public','tin_reference'] WHEN 'branches' THEN ARRAY['organization_id','code','name','location_public'] WHEN 'people' THEN ARRAY['code','branch_id'] WHEN 'attendance' THEN ARRAY['event_id','code','branch_id'] WHEN 'safeguarding' THEN ARRAY['code','branch_id'] ELSE ARRAY['code','name','title_public','purpose_public','reference','branch_id','fund_id','event_id','status','currency','amount','cost','capacity','facility_id','programme_id','organization_id','fund_id','budget_id','method','direction','period_start','period_end','source_url'] END; FOREACH k IN ARRAY allowed LOOP IF r.data ? k THEN d:=d||jsonb_build_object(k,r.data->k); END IF; END LOOP; RETURN jsonb_build_object('id',r.id,'workspace_id',r.workspace_id,'status',r.status,'version',r.version,'created_by',r.created_by,'created_at',r.created_at,'updated_at',r.updated_at)||d; END $$;
CREATE OR REPLACE FUNCTION public.office_institutions_read(p_workspace_id uuid,p_resource text,p_filter jsonb,p_limit integer,p_offset integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE f jsonb:=COALESCE(p_filter,'{}'::jsonb); n bigint; rows jsonb; actor_role text; s record; branch uuid; cap text; BEGIN
 IF NOT (p_resource='bootstrap' AND EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=auth.uid() AND m.role IN('owner','admin') AND m.status='active') AND NOT EXISTS(SELECT 1 FROM public.office_institutions_roles WHERE workspace_id=p_workspace_id AND active)) THEN PERFORM office_private.inst_require(p_workspace_id); END IF; IF jsonb_typeof(f)<>'object' OR p_limit NOT BETWEEN 1 AND 50 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid Institutions page request' USING ERRCODE='22023'; END IF;
 IF p_resource='bootstrap' THEN SELECT * INTO s FROM public.office_institutions_settings WHERE workspace_id=p_workspace_id; IF NOT FOUND THEN s.initialized:=false;s.version:=1;s.base_currency:='TZS';s.private_data_enabled:=false;s.storage_review_state:='unverified'; END IF; actor_role:=office_private.inst_role(p_workspace_id); RETURN jsonb_build_object('workspace_id',p_workspace_id,'role',actor_role,'capabilities',jsonb_build_object('manage',office_private.inst_cap(p_workspace_id,'manage'),'people',office_private.inst_cap(p_workspace_id,'people'),'governance',office_private.inst_cap(p_workspace_id,'governance'),'finance',office_private.inst_cap(p_workspace_id,'finance'),'approve',office_private.inst_cap(p_workspace_id,'approve'),'facilities',office_private.inst_cap(p_workspace_id,'facilities'),'programmes',office_private.inst_cap(p_workspace_id,'programmes'),'staff',office_private.inst_cap(p_workspace_id,'staff'),'safeguarding',office_private.inst_cap(p_workspace_id,'safeguarding'),'privacy',office_private.inst_cap(p_workspace_id,'privacy'),'reports',office_private.inst_cap(p_workspace_id,'reports'),'audit',office_private.inst_cap(p_workspace_id,'audit')),'settings',jsonb_build_object('initialized',s.initialized,'version',s.version,'base_currency',s.base_currency,'private_data_enabled',s.private_data_enabled,'storage_review_state',s.storage_review_state,'storage_review_reference',s.storage_review_reference,'storage_review_recorded_by',s.storage_review_recorded_by,'storage_reviewed_by',s.storage_reviewed_by),'summary',jsonb_build_object('organizations',(SELECT count(*) FROM public.office_institutions_records WHERE workspace_id=p_workspace_id AND resource='organizations'),'people',(SELECT count(*) FROM public.office_institutions_records WHERE workspace_id=p_workspace_id AND resource='people' AND office_private.inst_cap(p_workspace_id,'people') AND s.private_data_enabled AND s.storage_review_state='approved')),'scope_branch_id',(SELECT branch_id FROM public.office_institutions_roles WHERE workspace_id=p_workspace_id AND user_id=auth.uid() AND active AND role<>'institution_admin')); END IF;
 IF p_resource='private_keys' THEN IF office_private.inst_cap(p_workspace_id,'people') THEN cap:='people'; ELSIF office_private.inst_cap(p_workspace_id,'safeguarding') THEN cap:='safeguarding'; ELSE RAISE EXCEPTION 'Private key access denied' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('people',CASE WHEN office_private.inst_cap(p_workspace_id,'people') THEN COALESCE((SELECT jsonb_build_object('configured',configured,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',encode(salt,'base64'),'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64')) FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind='people'),jsonb_build_object('configured',false)) ELSE jsonb_build_object('configured',false) END,'safeguarding',CASE WHEN office_private.inst_cap(p_workspace_id,'safeguarding') AND (SELECT private_data_enabled AND storage_review_state='approved' FROM public.office_institutions_settings WHERE workspace_id=p_workspace_id) THEN COALESCE((SELECT jsonb_build_object('configured',configured,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',encode(salt,'base64'),'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64')) FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind='safeguarding'),jsonb_build_object('configured',false)) ELSE jsonb_build_object('configured',false) END); END IF;
 IF p_resource NOT IN('organizations','branches','bodies','people','appointments','meetings','resolutions','funds','budgets','contributions','payment_requests','bank_lines','reconciliations','facilities','assets','asset_moves','programmes','events','attendance','staff_assignments','credentials','filings','evidence','safeguarding','privacy_requests','reports','ledger','audit','team_members','roles','people_index','attendance_index','safeguarding_index') THEN RAISE EXCEPTION 'Unknown Institutions resource' USING ERRCODE='22023'; END IF;
 IF p_resource IN('people','attendance','safeguarding') THEN IF (f->>'id') IS NULL OR (f->>'purpose') NOT IN('administration','direct_service','record_correction','safeguarding_response','compliance_review') THEN RAISE EXCEPTION 'Sensitive reads require exact id and validated purpose' USING ERRCODE='55000'; END IF; END IF;
 IF p_resource IN('people_index','attendance_index','safeguarding_index') THEN cap:=CASE WHEN p_resource='people_index' THEN 'people' ELSE 'safeguarding' END; IF NOT office_private.inst_cap(p_workspace_id,cap) OR NOT EXISTS(SELECT 1 FROM public.office_institutions_keys WHERE workspace_id=p_workspace_id AND kind=CASE WHEN p_resource='people_index' THEN 'people' ELSE 'safeguarding' END AND configured) OR NOT EXISTS(SELECT 1 FROM public.office_institutions_settings WHERE workspace_id=p_workspace_id AND private_data_enabled AND storage_review_state='approved') THEN RAISE EXCEPTION 'Private index gate closed' USING ERRCODE='55000'; END IF; p_resource:=CASE WHEN p_resource='people_index' THEN 'people' WHEN p_resource='attendance_index' THEN 'attendance' ELSE 'safeguarding' END; END IF;
 branch:=NULLIF(f->>'branch_id','')::uuid; PERFORM office_private.inst_assert_scope(p_workspace_id,branch);
 SELECT count(*) INTO n FROM public.office_institutions_records x WHERE x.workspace_id=p_workspace_id AND x.resource=p_resource AND (f->>'id' IS NULL OR x.id=(f->>'id')::uuid) AND (f->>'status' IS NULL OR x.status=f->>'status') AND (f->>'q' IS NULL OR x.data::text ILIKE ('%'||(f->>'q')||'%')) AND (f->>'branch_id' IS NULL OR x.data->>'branch_id'=f->>'branch_id') AND (f->>'fund_id' IS NULL OR x.data->>'fund_id'=f->>'fund_id') AND (f->>'event_id' IS NULL OR x.data->>'event_id'=f->>'event_id') AND office_private.inst_scope(p_workspace_id,NULLIF(x.data->>'branch_id','')::uuid);
 SELECT COALESCE(jsonb_agg(z.v ORDER BY z.updated_at DESC,z.id),'[]'::jsonb) INTO rows FROM (SELECT x.*,CASE WHEN p_resource IN('people_index','attendance_index','safeguarding_index') THEN jsonb_build_object('id',x.id,'code',x.data->'code','status',x.status,'version',x.version,'branch_id',x.data->'branch_id','event_id',x.data->'event_id') ELSE office_private.inst_safe_row(x) END v FROM public.office_institutions_records x WHERE x.workspace_id=p_workspace_id AND x.resource=p_resource AND (f->>'id' IS NULL OR x.id=(f->>'id')::uuid) AND (f->>'status' IS NULL OR x.status=f->>'status') AND (f->>'branch_id' IS NULL OR x.data->>'branch_id'=f->>'branch_id') AND office_private.inst_scope(p_workspace_id,NULLIF(x.data->>'branch_id','')::uuid) ORDER BY x.updated_at DESC,x.id OFFSET p_offset LIMIT p_limit) z;
 INSERT INTO public.office_institutions_audit(workspace_id,actor_id,resource,action,purpose,metadata) VALUES(p_workspace_id,auth.uid(),p_resource,'read',f->>'purpose',jsonb_build_object('id',f->>'id','count',jsonb_array_length(rows))); RETURN jsonb_build_object('rows',rows,'total_count',n,'limit',p_limit,'offset',p_offset,'has_more',p_offset+jsonb_array_length(rows)<n);
END $$;
GRANT EXECUTE ON FUNCTION public.office_institutions_read(uuid,text,jsonb,integer,integer) TO authenticated;
COMMIT;
